import { notFound } from "next/navigation";
import { requireStoreAccess } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import VendorSection from "@/components/vendor-section";
import { PasswordChangeForm } from "@/components/password-change-form";
const titles:Record<string,string>={orders:"Sifarişlər",returns:"Qaytarılma müraciətləri",inventory:"Anbar qalığı",products:"Məhsullarım",imports:"Məhsulları toplu əlavə et",campaigns:"Kampaniyalar",sales:"Satış və gəlir",profile:"Mağazam",reviews:"Müştəri rəyləri",notifications:"Bildirişlər",subscription:"Abunəliyim",settings:"Hesab və parametrlər"};
export default async function Section({params}:{params:Promise<{storeId:string;section:string}>}){const {storeId,section}=await params;if(section==="security"){const access=await requireStoreAccess(storeId);if(!access)notFound();const account=await prisma.user.findUnique({where:{id:access.user.id},select:{passwordAuthEnabled:true}});return <section className="mx-auto max-w-3xl rounded-2xl border border-[#e7e3d9] bg-white p-5 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#967844]">Hesab təhlükəsizliyi</p><h1 className="mt-2 text-2xl font-semibold text-[#142d38]">Şifrəni dəyiş</h1><p className="mt-2 text-sm text-slate-600">Şifrə hesabınız üçündür və sahib olduğunuz bütün mağazalara girişdə istifadə olunur.</p>{account?.passwordAuthEnabled?<PasswordChangeForm/>:<p className="mt-2 text-sm text-slate-600">Bu hesab Google ilə idarə olunur; BAGATI şifrəsi dəyişdirilmir.</p>}<p className="mt-6 text-xs leading-5 text-slate-500">Şifrənizi unutmusunuzsa, <a className="underline" href="/forgot-password">bərpa keçidi istəyin</a>. Çoxmərhələli təsdiq hazırda təqdim edilmir.</p></section>}if(!titles[section])notFound();if(!await requireStoreAccess(storeId))notFound();return <VendorSection storeId={storeId} section={section} title={titles[section]}/>}
